import{_ as t,C as l,o as n,c as s,a5 as i,E as c,j as a,a as o}from"./chunks/framework.BwlBv862.js";const g=JSON.parse('{"title":"共同操作とチームアクセスを準備する","description":"","frontmatter":{"title":"共同操作とチームアクセスを準備する","docId":"user.cloud.collaboration","translationKey":"user.cloud.collaboration","locale":"ja","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"4a97f64b6bdc818ebb8d16eec1e67d95a2d0eae0b75f7cfd5c1493bf27244684","translationRevision":"996dba8cbb043d68b54ebf316c4e126b05b0f5233ffa3f46735961ed17dfb86d","order":30},"headers":[],"relativePath":"ja/user/cloud/collaboration.md","filePath":"ja/user/cloud/collaboration.md","lastUpdated":1794611623000}'),d={name:"ja/user/cloud/collaboration.md"};function u(p,e,b,h,m,f){const r=l("DemoFrame");return n(),s("div",null,[e[0]||(e[0]=i('<h1 id="prepare-collaboration-and-team-access" tabindex="-1">共同操作とチームアクセスを準備する <a class="header-anchor" href="#prepare-collaboration-and-team-access" aria-label="Permalink to &quot;共同操作とチームアクセスを準備する {#prepare-collaboration-and-team-access}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目的と前提条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目的と前提条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>所有者の管理権を保ち、別の操作担当者に範囲を定めた役割を付与します。対応デスクトップホストを用意し、ローカル・ネイティブ共同操作か、アカウント方式のチームかを意識して選びます。チームには <a href="./account.html">Cloud サインイン</a> と対応する配置済みサービスも必要です。まず本番以外の構成と読み取り専用権限で始めます。</p><h2 id="configure-owner-access" tabindex="-1">所有者側のアクセスを設定する <a class="header-anchor" href="#configure-owner-access" aria-label="Permalink to &quot;所有者側のアクセスを設定する {#configure-owner-access}&quot;">​</a></h2><ol><li><strong>設定 → 共同作業</strong> で接続状態を確認し、操作欄から対象のリスナーまたはゲートウェイを有効化・設定します。</li><li>招待作成前に許可オリジンとアクセス行列を確認します。担当者に必要な領域、操作、リソースだけを選びます。</li><li>招待を作り、非公開のリンク・トークンを信頼できる経路で渡します。招待は承認済みの有効なセッションとは異なります。</li><li>保留中の要求と要求された権限を確認します。想定した担当者だけを承認し、表示された本人情報と接続を確認します。</li><li>アクセスインスペクターで後の権限変更を確認します。不要になった招待、ID、セッションは取り消します。</li></ol><p>委任された定義編集、所有者としての定義採用、委任実行の承認は別の判断です。各確認画面で保存済みソース、参照アクション、権限を読みます。定義のプレビューだけでは実処理は許可されません。</p><h2 id="prepare-an-account-based-team" tabindex="-1">アカウント方式のチームを準備する <a class="header-anchor" href="#prepare-an-account-based-team" aria-label="Permalink to &quot;アカウント方式のチームを準備する {#prepare-an-account-based-team}&quot;">​</a></h2><p><strong>設定 → チーム</strong> が利用できる場合、名前付きチームを作成して選択します。識別しやすい端末名で <strong>このPC</strong> をホスト登録し、<strong>提供を開始</strong> を使ってリンク状態を確認します。作成とローカルホスト登録はフロントエンドに接続済みですが、仲間の招待とは別操作です。コントローラー端末には独自の登録役割があります。</p><p>宛先、役割、招待の有効期間を選び、受信要求、メンバー、端末を確認します。ニックネーム検索には別途配置されたバックエンドが必要で、現在のサービスでは使えない場合があります。検索失敗だけで未登録と判断せず、選択を迂回するために任意の ID を代入しないでください。</p><h2 id="expected-result-and-status" tabindex="-1">期待される結果と提供状況 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;期待される結果と提供状況 {#expected-result-and-status}&quot;">​</a></h2><p>所有者のアクセス制御と、フロントエンドのチーム作成・登録は実装されています。リモート共同操作全体は実験段階です。実際の2台の PC での LIVE、本番のニックネーム検索、NAT・リレーの挙動、全プラットフォームと実処理の復旧経路はここでは確認されていません。リンクが準備完了でも、目的の操作について全経路で権限が守られるとは証明できません。</p><h2 id="recovery" tabindex="-1">問題が起きたとき <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;問題が起きたとき {#recovery}&quot;">​</a></h2><p>権限やホストのリビジョンが古ければ再読み込みして再確認します。未確認コマンドは再試行前に記録済み結果を調べます。終了時は提供を停止するかアクセスを取り消します。招待トークンと認証情報を公開の<a href="./../preferences/troubleshooting.html">診断レポート</a> に含めないでください。</p>',13)),c(r,{scenario:"collaboration",locale:"ja",title:"デモ: 共同操作"}),e[1]||(e[1]=a("h2",{id:"operational-details",tabindex:"-1"},[o("運用の詳細 "),a("a",{class:"header-anchor",href:"#operational-details","aria-label":'Permalink to "運用の詳細 {#operational-details}"'},"​")],-1)),e[2]||(e[2]=a("p",null,[o("Teams 参加・承認後も host が現在版のネイティブ権限を確認します。"),a("code",null,"pendingHost"),o(" は未完了で、接続や所属だけではアクセスできません。権限変更後に再読し host/端末を確認します。observer は読み取り中心、moderator は限定運用制御、automationEditor は限定編集、custom は明示レビュー済み policy が必要です。無制限 script・外部効果は付与しません。拒否理由が UI で不明なら"),a("a",{href:"./../../developer/collaboration.html#operational-details"},"role と確認契約"),o("を参照します。")],-1))])}const q=t(d,[["render",u]]);export{g as __pageData,q as default};
